/*
 * "Is my Mazda supported?" checker for docs/getting-started/
 * supported-cars.md.
 *
 * Data comes from window.ZP_CARS
 * (docs/assets/js/car-checker-data.js), generated by the site repo's
 * sync script from the same source the main site's checker uses, so
 * both always agree. The questions mirror what the wiki documents:
 * model family first, then — for Mazdas outside the list — the steering
 * motor, because that is what the steering envelope keys on.
 */
(function () {
  "use strict";

  var mount = document.getElementById("zp-car-checker");
  var cars = window.ZP_CARS;
  if (!mount || !cars) return;

  mount.innerHTML = "";
  mount.className = "zp-checker";

  function option(value, label) {
    var o = document.createElement("option");
    o.value = value;
    o.textContent = label;
    return o;
  }

  var form = document.createElement("div");
  form.className = "zp-checker-form";

  var labelCar = document.createElement("label");
  labelCar.textContent = "Which Mazda?";
  var car = document.createElement("select");
  car.appendChild(option("", "Choose…"));
  car.appendChild(option("cx5", "CX-5, 2022–2025"));
  car.appendChild(option("cx9", "CX-9, 2021–2023"));
  car.appendChild(option("cx5old", "CX-5, 2017–2021"));
  car.appendChild(option("cx9old", "CX-9, 2016–2020"));
  car.appendChild(option("mazda3", "Mazda 3, 2017–2018"));
  car.appendChild(option("mazda6", "Mazda 6, 2017–2021"));
  car.appendChild(option("older", "An older or other Mazda"));
  labelCar.appendChild(car);

  var labelMotor = document.createElement("label");
  labelMotor.textContent = "Steering motor?";
  labelMotor.hidden = true;
  var motor = document.createElement("select");
  motor.appendChild(option("", "Choose…"));
  motor.appendChild(option("stock", "Original, never swapped"));
  motor.appendChild(option("swap", "2022–25 CX-5 motor swapped in"));
  motor.appendChild(option("unsure", "Not sure"));
  labelMotor.appendChild(motor);

  form.appendChild(labelCar);
  form.appendChild(labelMotor);
  mount.appendChild(form);

  var out = document.createElement("div");
  out.className = "zp-checker-out";
  out.setAttribute("role", "status");
  mount.appendChild(out);

  function verdict(title, body, good) {
    out.innerHTML = "";
    var t = document.createElement("strong");
    t.textContent = title;
    if (good === true) t.classList.add("is-good");
    if (good === false) t.classList.add("is-bad");
    var p = document.createElement("p");
    /* body may carry one {{EPS_SWAP}} placeholder for the eps-swap
     * page link; this page and eps-swap are siblings, and the wiki
     * builds with directory URLs, so the relative link is the page
     * directory name */
    p.innerHTML = body.replace(
      /\{\{EPS_SWAP\}\}/g,
      '<a href="eps-swap/">the EPS swap</a>',
    );
    out.appendChild(t);
    out.appendChild(p);
    out.hidden = false;
  }

  var rowFor = function (needle) {
    var found = null;
    cars.forEach(function (c) {
      if (c.car.toLowerCase().indexOf(needle) !== -1) found = c;
    });
    return found;
  };

  /* What a swap adds, from the matrix row's flags. The pre-2021 CX-9
   * is the one platform where alpha long does not follow the swap; the
   * Mazda 3 and Mazda 6 alpha support is not yet validated. */
  var swapAdds = function (row) {
    if (!row) return "";
    if (row.alphaLong === false) {
      return " The swap adds steer-to-zero, but not alpha longitudinal:" +
        " this platform's radar does not publish the track frames the" +
        " port stands in for.";
    }
    if (row.alphaLong === "unknown") {
      return " The swap adds steer-to-zero; alpha longitudinal is built" +
        " to work here but has not been validated on this platform yet.";
    }
    return " The 2022-25 CX-5 EPS swap adds steer-to-zero and alpha" +
      " longitudinal.";
  };

  function renderMotor() {
    labelMotor.hidden = car.value !== "older";
    if (car.value !== "older") return;
    if (motor.value === "swap") {
      verdict(
        "Supported — the swap is what does it.",
        "The 2022-25 CX-5 EPS motor identifies by firmware: steering works" +
          " down to 0 mph and alpha longitudinal turns on — radar and AEB" +
          " off while it is on. The pre-2021 CX-9 is the one exception:" +
          " its radar does not publish the track frames, so alpha long" +
          " stays off.",
        true,
      );
    } else if (motor.value === "stock") {
      verdict(
        "Supported — on the stock steering envelope.",
        "zoompilot runs on the stock motor with the stock torque envelope: no steer-to-zero. {{EPS_SWAP}} unlocks steering down to 0 mph, with alpha longitudinal available (radar and AEB off while it is on).",
        true,
      );
    } else if (motor.value === "unsure") {
      verdict(
        "Check the motor first.",
        "Support depends on which steering motor the car has, not just the model year. {{EPS_SWAP}} explains what to look for, or ask on the Discord with your model year.",
      );
    } else {
      out.hidden = true;
    }
  }

  motor.addEventListener("change", renderMotor);
  car.addEventListener("change", function () {
    out.hidden = true;
    motor.value = "";
    renderMotor();
    if (car.value === "cx5") {
      verdict(
        "Supported — this is the primary target.",
        "Steer-to-zero and alpha longitudinal are native to this motor;" +
          " steering works down to 0 mph.",
        true,
      );
    } else if (car.value === "cx9") {
      verdict(
        "Supported — on the stock steering envelope.",
        "On the stock motor it runs speed-limited, no steer-to-zero." +
          swapAdds(rowFor("CX-9 2021")),
        true,
      );
    } else if (car.value === "cx5old") {
      verdict(
        "Supported — on the stock steering envelope.",
        "On the stock motor it runs speed-limited, no steer-to-zero." +
          swapAdds(rowFor("CX-5 2017")),
        true,
      );
    } else if (car.value === "cx9old") {
      verdict(
        "Supported — on the stock steering envelope.",
        "On the stock motor it runs speed-limited, no steer-to-zero." +
          swapAdds(rowFor("CX-9 2016")),
        true,
      );
    } else if (car.value === "mazda3" || car.value === "mazda6") {
      var row = rowFor(car.value === "mazda3" ? "Mazda 3" : "Mazda 6");
      verdict(
        "Reported working.",
        "Runs on the stock motor: speed-limited, no steer-to-zero." +
          swapAdds(row) +
          " Community-reported, with fewer test miles than the CX-5 and" +
          " CX-9 rows.",
      );
    } else if (car.value === "older") {
      renderMotor();
    } else {
      out.hidden = true;
      out.innerHTML = "";
    }
  });
})();
